pub struct Buf { q: Mutex<Vec<i32>>, cv: Condvar }
impl Buf {
    pub fn take(&self) -> i32 {
        let mut q = self.cv.wait_while(self.q.lock().unwrap(), |q| q.is_empty())
            .unwrap();                       // wait_while re-checks the predicate
        q.remove(0)
    }
    pub fn put(&self, v: i32) {
        self.q.lock().unwrap().push(v);   // change state first
        self.cv.notify_one();             // then wake one waiter
    }
}

