async fn recv(q: &Mutex<VecDeque<T>>, notify: &Notify) -> T {
    loop {
        if let Some(v) = q.lock().unwrap().pop_front() {
            return v;                     // predicate already satisfied
        }
        notify.notified().await;          // suspends the task, not a thread
    }
}
